script:
(function () {
  'use strict';
  // 401(k) spend it or save it. A raise or bonus is either taken as pay or deferred into the
  // 401(k) (up to the room left under the 2026 elective deferral limit; any excess is paid out).
  //   Spend:  take-home = gross x (1 - federal - state - FICA)
  //   Save:   deferral d = min(gross, limit - deferrals already made); FICA is still due on d,
  //           so take-home given up = d x (1 - federal - state) and income tax saved = d x (federal + state).
  //           Employer match = d x match %.
  // A bonus is deposited once at the start; a raise is deposited monthly each year, growing with pay.
  // The balance compounds monthly at (1 + annual return)^(1/12) - 1. After tax at retirement =
  // balance x (1 - retirement tax). Taxable comparison: the same take-home given up, invested in
  // a brokerage account, with capital gains tax on the growth at retirement.
  // CHECKS (Node, scratch tests): $5,000 bonus, 22% + 5%, FICA 7.65%: take-home $3,267.50, given
  // up $3,650, tax saved $1,350; $5,000 at 6% for 30 years = 5,000 x 1.06^30 = $28,717.46; a
  // $1,200 raise with 0% growth for 1 year at 0% return = $1,200; $1,200 a year
  // ($100/month) for 30 years at 6% = 100 x ((1 + i)^360 - 1) / i = $97,451.30; age 40 with $20,000 deferred
  // leaves $4,500 room (age 55: $12,500; age 61: $15,750); 50% match on $5,000 = $2,500.
  // ---- 2026 IRS 401(k) limits (IRS Notice 2025-67, tax year 2026) ------------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,      // 402(g) elective deferral limit (pre-tax + Roth)
    catchUp50: 8000,      // catch-up, age 50 or older by year-end
    catchUp60to63: 11250  // SECURE 2.0 higher catch-up for ages 60 to 63
  };
  // -----------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }
  function deferralLimit(age) { return LIMITS.deferral + catchUpFor(age); }

  // p: amount, raise (bool), growth, age, retireAge, current, match, fed, state, fica,
  // retireTax, rate, cg (rates as decimals).
  function compare(p) {
    var n = p.retireAge - p.age, tax = p.fed + p.state, i = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = 0, brk = 0, basis = 0, rows = [], capped = false;
    var t = { gross: 0, spend: 0, defer: 0, match: 0, saved: 0, given: 0 };
    for (var y = 0; y < n; y++) {
      var age = p.age + y;
      var gross = p.raise ? p.amount * Math.pow(1 + p.growth, y) : (y === 0 ? p.amount : 0);
      var room = Math.max(0, deferralLimit(age) - p.current);
      var d = Math.min(gross, room);
      if (gross > room + 0.005) capped = true;
      var m = d * p.match, given = d * (1 - tax), spend = gross * (1 - tax - p.fica);
      if (p.raise) {
        for (var k = 0; k < 12; k++) {
          bal = bal * (1 + i) + (d + m) / 12;
          brk = brk * (1 + i) + given / 12;
        }
      } else {
        bal = (bal + d + m) * Math.pow(1 + i, 12);
        brk = (brk + given) * Math.pow(1 + i, 12);
      }
      basis += given;
      t.gross += gross; t.spend += spend; t.defer += d; t.match += m; t.saved += d * tax; t.given += given;
      rows.push({ age: age, spend: spend, d: d, m: m, bal: bal });
    }
    var brkAfter = brk - p.cg * Math.max(0, brk - basis);
    return { n: n, bal: bal, after: bal * (1 - p.retireTax), brkAfter: brkAfter, t: t, rows: rows, capped: capped };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 || !isFinite(x) ? 0 : x); } };
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var raise = document.getElementById('ksType').value === 'raise';
    document.getElementById('ksRaiseGroup').hidden = !raise;
    var amount = num('ksAmount'), growth = num('ksGrowth'), age = Math.round(num('ksAge')),
        retireAge = Math.round(num('ksRetireAge')), current = num('ksCurrent'), match = num('ksMatch'),
        fed = num('ksFed'), state = num('ksState'), retireTax = num('ksRetireTax'), rate = num('ksReturn'),
        fica = num('ksFica'), cg = num('ksCg');
    var error = document.getElementById('ksError');
    var bad = [amount, growth, age, retireAge, current, match, fed, state, retireTax, rate, fica, cg].some(isNaN) ||
              amount < 0 || growth < 0 || growth > 20 || age < 16 || age > 99 || retireAge <= age || retireAge > 100 ||
              current < 0 || match < 0 || match > 200 || fed < 0 || fed > 50 || state < 0 || state > 20 ||
              fica < 0 || fica > 20 || fed + state + fica >= 100 || retireTax < 0 || retireTax > 60 ||
              rate < 0 || rate > 20 || cg < 0 || cg > 40;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, an age from 16 to 99 with a retirement age above it (up to 100), ' +
                          'tax rates within the limits shown, a match up to 200% and a return up to 20%.';
      return;
    }
    var r = compare({ amount: amount, raise: raise, growth: growth / 100, age: age, retireAge: retireAge, current: current,
                      match: match / 100, fed: fed / 100, state: state / 100, fica: fica / 100,
                      retireTax: retireTax / 100, rate: rate / 100, cg: cg / 100 });
    set('ksBalanceLabel', '401(k) value at age ' + retireAge);
    set('ksBalance', money.format(r.bal));
    set('ksAfterTax', money.format(r.after));
    set('ksSpendNow', money.format(r.t.spend));
    set('ksGivenUp', money.format(r.t.given));
    set('ksTaxSaved', money.format(r.t.saved));
    set('ksMatchTotal', money.format(r.t.match));
    var what = raise ? 'the raise' : 'the bonus';
    if (r.t.defer <= 0) {
      set('ksSummary', amount > 0 ? 'You have no room left under the ' + LIMITS.year + ' deferral limit, so all of ' + what +
          ' would be paid to you.' : 'Enter the amount of your raise or bonus.');
      set('ksTaxableNote', '');
    } else {
      set('ksSummary', 'Spending ' + what + ' gives you ' + money.format(r.t.spend) + ' of take-home pay' +
          (raise ? ' over ' + r.n + ' years' : '') + '. Saving it costs you ' + money.format(r.t.given) +
          ' of take-home pay and leaves ' + money.format(r.after) + ' after tax at age ' + retireAge +
          ', or ' + cents.format(r.after / r.t.given) + ' for each $1 of take-home pay you give up.');
      set('ksTaxableNote', 'The same ' + money.format(r.t.given) + ' invested in a taxable brokerage account would be worth about ' +
          money.format(r.brkAfter) + ' after capital gains tax.');
    }
    var capNote = document.getElementById('ksCapped');
    capNote.hidden = !r.capped;
    if (r.capped) capNote.textContent = 'Part of ' + what + ' is above your remaining room under the ' + LIMITS.year +
      ' deferral limit, so that part is treated as paid to you in the saving option.';
    var body = document.getElementById('ksSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.spend), money.format(row.d), money.format(row.m), money.format(row.bal)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ksForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
